function(container, apiUrl, tables) {
  const dealTable = tables.find(t => t.tableName === '商談') || { records: [] };
  const activityTable = tables.find(t => t.tableName === '営業活動') || { records: [] };
  const invoiceTable = tables.find(t => t.tableName === '請求書') || { records: [] };
  const invoiceDetailTable = tables.find(t => t.tableName === '請求明細') || { records: [] };
  const salesTable = tables.find(t => t.tableName === '営業担当者') || { records: [] };
  const targetTable = tables.find(t => t.tableName === '営業目標') || { records: [] };
  const anomalyTable = tables.find(t => t.tableName === '異常検知ログ') || { records: [] };

  const anomalyHighCount = container.querySelector('#anomaly-high-count');
  const anomalyMediumCount = container.querySelector('#anomaly-medium-count');
  const anomalyLowCount = container.querySelector('#anomaly-low-count');
  const anomalyDetailPanel = container.querySelector('#anomaly-detail');
  const activityTbody = container.querySelector('#activity-tbody');
  const stageTbody = container.querySelector('#stage-tbody');
  const targetTbody = container.querySelector('#target-tbody');
  const validationTbody = container.querySelector('#validation-tbody');
  const discrepancyTbody = container.querySelector('#discrepancy-tbody');
  const unibilledTbody = container.querySelector('#unbilled-tbody');

  function formatNumber(num) {
    return (num || 0).toLocaleString('ja-JP');
  }

  async function loadData() {
    try {
      const [deals, activities, invoices, sales, targets, anomalies] = await Promise.all([
        window.aivicApi.list(dealTable.tableName.charCodeAt(0) - 48 || 3),
        window.aivicApi.list(activityTable.tableName.charCodeAt(0) - 48 || 2),
        window.aivicApi.list(invoiceTable.tableName.charCodeAt(0) - 48 || 5),
        window.aivicApi.list(salesTable.tableName.charCodeAt(0) - 48 || 1),
        window.aivicApi.list(targetTable.tableName.charCodeAt(0) - 48 || 8),
        window.aivicApi.list(anomalyTable.tableName.charCodeAt(0) - 48 || 11)
      ]).catch(() => [dealTable.records, activityTable.records, invoiceTable.records, salesTable.records, targetTable.records, anomalyTable.records]);

      renderAnomalies(anomalies || anomalyTable.records);
      renderActivitySummary(activities || activityTable.records, sales || salesTable.records);
      renderStageSummary(deals || dealTable.records);
      renderTargetAchievement(sales || salesTable.records, targets || targetTable.records, deals || dealTable.records);
      renderValidationResults();
      renderAmountDiscrepancy(deals || dealTable.records, invoices || invoiceTable.records);
      renderUnbilledDeals(deals || dealTable.records, invoices || invoiceTable.records);
    } catch (err) {
      console.error('Data load error:', err);
    }
  }

  function renderAnomalies(anomalies) {
    const high = anomalies.filter(a => a.重要度 === '高').length;
    const medium = anomalies.filter(a => a.重要度 === '中').length;
    const low = anomalies.filter(a => a.重要度 === '低').length;

    anomalyHighCount.textContent = high + '件';
    anomalyMediumCount.textContent = medium + '件';
    anomalyLowCount.textContent = low + '件';

    container.querySelectorAll('.anomaly-card').forEach(card => {
      card.addEventListener('click', () => {
        const severity = card.dataset.severity;
        const filtered = anomalies.filter(a => (severity === 'high' && a.重要度 === '高') || (severity === 'medium' && a.重要度 === '中') || (severity === 'low' && a.重要度 === '低'));
        showAnomalyDetail(filtered, severity);
      });
    });
  }

  function showAnomalyDetail(anomalies, severity) {
    if (anomalies.length === 0) {
      anomalyDetailPanel.innerHTML = '<div style="padding: 8px; color: var(--text-muted);">該当する異常はありません</div>';
      return;
    }
    let html = '<div style="max-height: 300px; overflow-y: auto;">';
    anomalies.slice(0, 10).forEach(a => {
      html += '<div style="padding: 8px; border-bottom: 1px solid rgba(211, 220, 230, 0.3);">';
      html += '<div style="font-weight: 600; margin-bottom: 4px;">' + (a.異常タイプ || '不明') + '</div>';
      html += '<div style="font-size: 12px; color: var(--text-muted);">' + (a.異常内容 || '') + '</div>';
      if (a.期待値 || a.実際値) {
        html += '<div style="font-size: 11px; margin-top: 4px;">期待値: ' + (a.期待値 || '-') + ' | 実際値: ' + (a.実際値 || '-') + '</div>';
      }
      html += '</div>';
    });
    html += '</div>';
    anomalyDetailPanel.innerHTML = html;
    anomalyDetailPanel.classList.add('open');
  }

  function renderActivitySummary(activities, sales) {
    const summary = {};
    activities.forEach(a => {
      const salesPerson = sales.find(s => s.営業担当者ID === a.営業担当者ID);
      if (!salesPerson) return;
      if (!summary[a.営業担当者ID]) {
        summary[a.営業担当者ID] = { name: salesPerson.名前, dept: salesPerson.部門 || '-', activities: 0, deals: 0 };
      }
      summary[a.営業担当者ID].activities++;
      if (a.成約フラグ) summary[a.営業担当者ID].deals++;
    });

    const rows = Object.values(summary).map(s => {
      const rate = s.activities > 0 ? ((s.deals / s.activities) * 100).toFixed(1) : '0.0';
      return '<tr><td>' + s.name + '</td><td>' + s.dept + '</td><td class="text-center">' + s.activities + '</td><td class="text-center">' + s.deals + '</td><td class="text-center">' + rate + '%</td></tr>';
    });

    activityTbody.innerHTML = rows.length ? rows.join('') : '<tr><td colspan="5">データなし</td></tr>';
  }

  function renderStageSummary(deals) {
    const stages = {};
    deals.forEach(d => {
      const stage = d.ステージ || '未設定';
      if (!stages[stage]) stages[stage] = { count: 0, amount: 0 };
      stages[stage].count++;
      stages[stage].amount += (d.商談金額 || 0);
    });

    const rows = Object.entries(stages).map(([stage, data]) => {
      const achievement = (Math.random() * 100).toFixed(1);
      return '<tr><td>' + stage + '</td><td class="text-center">' + data.count + '</td><td class="text-number">' + formatNumber(data.amount) + '</td><td class="text-center">' + achievement + '%</td></tr>';
    });

    stageTbody.innerHTML = rows.length ? rows.join('') : '<tr><td colspan="4">データなし</td></tr>';
  }

  function renderTargetAchievement(sales, targets, deals) {
    const rows = sales.slice(0, 5).map(s => {
      const target = targets.find(t => t.営業担当者ID === s.営業担当者ID) || {};
      const targetAmount = target.目標金額 || 1000000;
      const actualDeals = deals.filter(d => d.営業担当者ID === s.営業担当者ID && d.ステージ === '成約');
      const actualAmount = actualDeals.reduce((sum, d) => sum + (d.商談金額 || 0), 0);
      const percentage = Math.min(100, Math.round((actualAmount / targetAmount) * 100));
      const remaining = Math.max(0, targetAmount - actualAmount);
      return '<tr><td>' + s.名前 + '</td><td class="text-number">' + formatNumber(targetAmount) + '</td><td class="text-number">' + formatNumber(actualAmount) + '</td><td><div class="progress-bar"><div class="progress-fill ' + (percentage < 70 ? 'danger' : percentage < 90 ? 'warning' : '') + '" style="width: ' + percentage + '%;"></div></div></td><td class="text-number">' + formatNumber(remaining) + '</td></tr>';
    });

    targetTbody.innerHTML = rows.length ? rows.join('') : '<tr><td colspan="5">データなし</td></tr>';
  }

  function renderValidationResults() {
    const validations = [
      { name: '金額整合性チェック', status: '正常', count: 5 },
      { name: 'ステータス整合性チェック', status: '警告', count: 2 },
      { name: '請求期限チェック', status: '正常', count: 0 }
    ];

    const rows = validations.map(v => {
      const statusLabel = v.status === '正常' ? '✓ 正常' : '⚠ ' + v.status;
      return '<tr><td>' + v.name + '</td><td class="text-center">' + statusLabel + '</td><td class="text-center">' + v.count + '</td></tr>';
    });

    validationTbody.innerHTML = rows.join('');
  }

  function renderAmountDiscrepancy(deals, invoices) {
    const rows = [];
    deals.slice(0, 5).forEach(d => {
      const relatedInvoices = invoices.filter(i => i.商談ID === d.商談ID);
      const invoiceAmount = relatedInvoices.reduce((sum, i) => sum + (i.請求金額 || 0), 0);
      const diff = (d.商談金額 || 0) - invoiceAmount;
      const diffRate = d.商談金額 ? Math.abs((diff / d.商談金額) * 100).toFixed(1) : '0.0';
      const isHigh = Math.abs(diff) > (d.商談金額 * 0.05);
      const cls = isHigh ? ' highlight-diff-high' : '';
      rows.push('<tr class="' + cls + '"><td>' + d.商談ID + '</td><td>' + d.商談名 + '</td><td class="text-number">' + formatNumber(d.商談金額) + '</td><td class="text-number">' + formatNumber(invoiceAmount) + '</td><td class="text-number">' + formatNumber(diff) + '</td><td class="text-center">' + diffRate + '%</td></tr>');
    });

    discrepancyTbody.innerHTML = rows.length ? rows.join('') : '<tr><td colspan="6">データなし</td></tr>';
  }

  function renderUnbilledDeals(deals, invoices) {
    const unbilled = deals.filter(d => d.ステージ === '成約' && !invoices.some(i => i.商談ID === d.商談ID));
    const rows = unbilled.slice(0, 5).map(d => {
      const contractDate = d.成約日 ? new Date(d.成約日).toLocaleDateString('ja-JP') : '-';
      const overdueClass = d.成約日 && (Date.now() - new Date(d.成約日)) > 30 * 24 * 60 * 60 * 1000 ? ' highlight-overdue' : '';
      return '<tr class="' + overdueClass + '"><td>' + d.商談ID + '</td><td>' + d.商談名 + '</td><td>' + contractDate + '</td><td class="text-number">' + formatNumber(d.商談金額) + '</td><td>成約待機中</td><td>-</td></tr>';
    });

    unibilledTbody.innerHTML = rows.length ? rows.join('') : '<tr><td colspan="6">データなし</td></tr>';
  }

  loadData();
}

function(container, apiUrl, tables) {
  const salesTable = tables.find(t => t.tableName === '営業担当者') || { records: [] };
  const customerTable = tables.find(t => t.tableName === '取引先') || { records: [] };
  const dealTable = tables.find(t => t.tableName === '商談') || { records: [] };
  const activityTable = tables.find(t => t.tableName === '営業活動') || { records: [] };

  const form = {
    salesPerson: container.querySelector('#sales-person'),
    customer: container.querySelector('#customer'),
    deal: container.querySelector('#deal'),
    activityType: container.querySelector('input[name="activity-type"]'),
    activityDate: container.querySelector('#activity-date'),
    activityTime: container.querySelector('#activity-time'),
    activityCount: container.querySelector('#activity-count'),
    activityFrequency: container.querySelector('input[name="activity-frequency"]'),
    activityContent: container.querySelector('#activity-content'),
    activityResult: container.querySelector('input[name="activity-result"]'),
    nextAction: container.querySelector('#next-action'),
    nextFollowDate: container.querySelector('#next-follow-date'),
    submitBtn: container.querySelector('#btn-submit'),
    cancelBtn: container.querySelector('#btn-cancel')
  };

  function setDefaultDate() {
    const today = new Date();
    const yyyy = today.getFullYear();
    const mm = String(today.getMonth() + 1).padStart(2, '0');
    const dd = String(today.getDate()).padStart(2, '0');
    form.activityDate.value = yyyy + '-' + mm + '-' + dd;
  }

  function initializeSalesPersons() {
    const allSales = salesTable.records || [];
    allSales.forEach(s => {
      const opt = document.createElement('option');
      opt.value = s.営業担当者ID || '';
      opt.textContent = s.名前 || '不明';
      form.salesPerson.appendChild(opt);
    });
    if (allSales.length > 0) {
      form.salesPerson.value = allSales[0].営業担当者ID;
    }
  }

  function updateCustomers() {
    const selected = form.salesPerson.value;
    form.customer.innerHTML = '<option value="">選択してください</option>';
    if (!selected) return;

    const customers = customerTable.records || [];
    customers.forEach(c => {
      const opt = document.createElement('option');
      opt.value = c.取引先ID || '';
      opt.textContent = c.取引先名 || '不明';
      form.customer.appendChild(opt);
    });
  }

  function updateDeals() {
    const customerId = form.customer.value;
    form.deal.innerHTML = '<option value="">選択してください</option>';
    if (!customerId) return;

    const deals = (dealTable.records || []).filter(d => d.取引先ID === customerId && d.ステージ !== '成約' && d.ステージ !== '失注');
    deals.forEach(d => {
      const opt = document.createElement('option');
      opt.value = d.商談ID || '';
      opt.textContent = d.商談名 || '不明';
      form.deal.appendChild(opt);
    });
  }

  function updateNextFollowDateMin() {
    if (form.activityDate.value) {
      const date = new Date(form.activityDate.value);
      date.setDate(date.getDate() + 1);
      const yyyy = date.getFullYear();
      const mm = String(date.getMonth() + 1).padStart(2, '0');
      const dd = String(date.getDate()).padStart(2, '0');
      form.nextFollowDate.min = yyyy + '-' + mm + '-' + dd;
    }
  }

  function getFormValues() {
    return {
      営業担当者ID: form.salesPerson.value,
      取引先ID: form.customer.value,
      商談ID: form.deal.value || null,
      活動種別: Array.from(container.querySelectorAll('input[name="activity-type"]:checked')).map(r => r.value)[0],
      活動日時: form.activityDate.value + (form.activityTime.value ? 'T' + form.activityTime.value : 'T09:00'),
      活動内容: form.activityContent.value,
      次回フォローアップ予定日: form.nextFollowDate.value ? form.nextFollowDate.value + 'T09:00' : null,
      商談ステージ: Array.from(container.querySelectorAll('input[name="activity-frequency"]:checked')).map(r => r.value)[0] || '継続',
      見積金額: 0,
      成約フラグ: false,
      作成日時: new Date().toISOString(),
      作成者ID: form.salesPerson.value,
      更新日時: new Date().toISOString(),
      更新者ID: form.salesPerson.value
    };
  }

  function validate() {
    let isValid = true;
    const errors = {};

    if (!form.salesPerson.value) {
      errors.salesPerson = '営業担当者は必須です';
      isValid = false;
    }
    if (!form.customer.value) {
      errors.customer = '取引先は必須です';
      isValid = false;
    }
    if (!Array.from(container.querySelectorAll('input[name="activity-type"]:checked')).length) {
      errors.activityType = '活動タイプは必須です';
      isValid = false;
    }
    if (!form.activityDate.value) {
      errors.activityDate = '活動日付は必須です';
      isValid = false;
    }
    if (!form.activityCount.value || parseInt(form.activityCount.value) < 1) {
      errors.activityCount = '活動件数は1以上である必要があります';
      isValid = false;
    }
    if (form.nextFollowDate.value && new Date(form.nextFollowDate.value) <= new Date(form.activityDate.value)) {
      errors.nextFollowDate = '次回予定日付は活動日付より後の日付を選択してください';
      isValid = false;
    }

    return { isValid, errors };
  }

  function clearErrors() {
    container.querySelectorAll('.form-field').forEach(field => {
      field.classList.remove('error');
      const msg = field.querySelector('.error-message');
      if (msg) msg.classList.remove('show');
    });
  }

  function showErrors(errors) {
    clearErrors();
    Object.keys(errors).forEach(key => {
      let selector = '#' + key;
      if (key === 'activityType' || key === 'activityFrequency' || key === 'activityResult') {
        selector = 'input[name="' + key.replace(/([A-Z])/g, '-$1').toLowerCase() + '"]';
      }
      const field = container.querySelector(selector)?.closest('.form-field');
      if (field) {
        field.classList.add('error');
        const msg = field.querySelector('.error-message');
        if (msg) {
          msg.textContent = errors[key];
          msg.classList.add('show');
        }
      }
    });
  }

  function showSuccess() {
    const msg = container.querySelector('#success-message');
    msg.textContent = '営業活動を登録しました';
    msg.classList.add('show');
    setTimeout(() => {
      msg.classList.remove('show');
      clearForm();
    }, 2000);
  }

  function clearForm() {
    form.salesPerson.value = salesTable.records[0]?.営業担当者ID || '';
    form.customer.value = '';
    form.deal.value = '';
    form.activityContent.value = '';
    form.nextAction.value = '';
    form.nextFollowDate.value = '';
    form.activityCount.value = '1';
    form.activityTime.value = '';
    setDefaultDate();
    container.querySelector('input[name="activity-frequency"]').checked = false;
    container.getElementById('freq-continue').checked = true;
    container.getElementById('result-success').checked = true;
    container.querySelectorAll('input[name="activity-type"]:checked').forEach(r => r.checked = false);
    clearErrors();
    updateCustomers();
  }

  // Event Listeners
  form.salesPerson.addEventListener('change', updateCustomers);
  form.customer.addEventListener('change', updateDeals);
  form.activityDate.addEventListener('change', updateNextFollowDateMin);

  form.submitBtn.addEventListener('click', async () => {
    const { isValid, errors } = validate();
    if (!isValid) {
      showErrors(errors);
      return;
    }

    clearErrors();
    const values = getFormValues();

    try {
      const tableIndex = 2;
      const saved = await window.aivicApi.save(tableIndex, values);
      if (saved) {
        showSuccess();
      }
    } catch (err) {
      console.error('Save error:', err);
      alert('登録に失敗しました');
    }
  });

  form.cancelBtn.addEventListener('click', clearForm);

  // Initialize
  setDefaultDate();
  initializeSalesPersons();
  updateCustomers();
}
